from typing import Dict, Any

def create_text_content_safety_request(text: str) -> Dict[str, Any]:
    return {
        'text': text
    }

def parse_text_content_safety_response(response: Dict[str, Any]) -> Dict[str, Any]:
    return {
        'safety_score': response.get('safety_score', None),
        'categories': response.get('categories', [])
    }

def normalize_text_content_safety_score(score: float) -> float:
    return max(0, min(1, score))

import boto3

def apply_thresholds(text):
    comprehend = boto3.client('comprehend')
    response = comprehend.detect_sentiment(Text=text, LanguageCode='en')
    sentiment = response['Sentiment']
    score = response['SentimentScore'][sentiment]
    thresholds = {'POSITIVE': 0.5, 'NEGATIVE': 0.3, 'NEUTRAL': 0.2}
    if sentiment in thresholds and score >= thresholds[sentiment]:
        return True
    return False

if __name__ == '__main__':
    text = 'Your text here'
    if apply_thresholds(text):
        print('Text allowed')
    else:
        print('Text not allowed')

import boto3

def redact_unsafe(text):
    comprehend = boto3.client('comprehend')
    response = comprehend.detect_sentiment(Text=text, LanguageCode='en')
    sentiment = response['Sentiment']
    if sentiment == 'NEGATIVE':
        return '[REDACTED]'
    else:
        return text
